\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Volatile Aroma Development in Alpine Cheese During Ripening:
A Sensory and Chemical Study}
\author{C.~Brunner, E.~Salis, and F.~Moreau}
\date{July 2026}

\begin{document}
\maketitle

\section{Ripening Protocol}
Wheels were ripened at 12 degrees Celsius and 92 percent relative
humidity, turned weekly, and brushed with a brine smear.
Sampling for sensory and chemical analysis took place at 30, 60,
90, and 180 days.

